<?php require __DIR__.'/includes/session.php'; require __DIR__.'/includes/db.php'; $uid=(int)$_SESSION['user_id']; $st=mysqli_prepare($conn,"SELECT c.id,c.product_id,c.quantity,p.name,p.price,p.image,p.stock FROM cart c JOIN products p ON c.product_id=p.id WHERE c.user_id=? ORDER BY c.id DESC");mysqli_stmt_bind_param($st,'i',$uid);mysqli_stmt_execute($st);$res=mysqli_stmt_get_result($st);$total=0; ?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cart | ClassyCubic</title><link rel="stylesheet" href="css/style.css"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><div class="page-wrap"><h2>Your Shopping Cart</h2><form method="POST" action="api/update_cart.php"><table class="cart-table"><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th>Action</th></tr><?php if(mysqli_num_rows($res)===0): ?><tr><td colspan="5">Your cart is empty.</td></tr><?php endif; ?><?php while($item=mysqli_fetch_assoc($res)): $sub=$item['price']*$item['quantity'];$total+=$sub; ?><tr><td><img src="<?php echo htmlspecialchars($item['image']); ?>" alt=""><br><?php echo htmlspecialchars($item['name']); ?></td><td>৳<?php echo number_format($item['price'],2); ?></td><td><input class="qty-box" type="number" name="qty[<?php echo (int)$item['product_id']; ?>]" min="0" max="<?php echo (int)$item['stock']; ?>" value="<?php echo (int)$item['quantity']; ?>"></td><td>৳<?php echo number_format($sub,2); ?></td><td><button class="btn-small btn-danger" type="submit" name="remove" value="<?php echo (int)$item['product_id']; ?>">Remove</button></td></tr><?php endwhile; ?></table><?php if($total>0): ?><div class="total-box"><h3>Total: ৳<?php echo number_format($total,2); ?></h3><button class="btn-secondary" type="submit" name="update">Update Cart</button> <a class="btn-primary" href="checkout.php">Checkout</a></div><?php endif; ?></form></div><footer><p>© 2026 ClassyCubic</p></footer><script src="js/cart.js"></script></body></html>